package qzwx.app.feature_home.screen

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material3.Button
import androidx.compose.material3.OutlinedTextField
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.KeyboardType
import qzwx.app.feature_home.viewmodel.HomePage_VM
import qzwx.app.module_data.entity.BillType
import qzwx.app.module_data.entity.QBillEntity


@Composable
fun HomePage(
    viewModel: HomePage_VM
) {
    Column(
        modifier = Modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        var amount by rememberSaveable { mutableIntStateOf(0) }
        var category by rememberSaveable { mutableStateOf("") }
        OutlinedTextField(
            value = amount.toString(), onValueChange = { amount = it.toInt() },
            keyboardOptions = KeyboardOptions.Default.copy(keyboardType = KeyboardType.Number),
            placeholder = { Text(text = "金额") }
        )
        OutlinedTextField(
            value = category, onValueChange = { category = it },
            keyboardOptions = KeyboardOptions.Default.copy(keyboardType = KeyboardType.Text),
            placeholder = { Text(text = "种类") }
        )
        Button(
            onClick = {
                viewModel.insertBill(
                    QBillEntity(
                        amount = amount.toLong(),
                        type = BillType.EXPENSE,
                        category = category,
                    )
                )
            }
        ) {
            Text(text = "添加")
        }
    }
}

package qzwx.app.feature_home.screen

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material3.Button
import androidx.compose.material3.OutlinedTextField
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.KeyboardType
import qzwx.app.feature_home.viewmodel.HomePage_VM
import qzwx.app.module_data.entity.BillType
import qzwx.app.module_data.entity.QBillEntity


@Composable
fun HomePage(
    viewModel: HomePage_VM
) {
    Column(
        modifier = Modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        var amount by rememberSaveable { mutableStateOf("") }
        var category by rememberSaveable { mutableStateOf("") }
        OutlinedTextField(
            value = amount, onValueChange = { amount = it },
            keyboardOptions = KeyboardOptions.Default.copy(keyboardType = KeyboardType.Number),
            placeholder = { Text(text = "金额") }
        )
        OutlinedTextField(
            value = category, onValueChange = { category = it },
            keyboardOptions = KeyboardOptions.Default.copy(keyboardType = KeyboardType.Text),
            placeholder = { Text(text = "种类") }
        )
        Button(
            onClick = {
                viewModel.insertBill(
                    QBillEntity(
                        amount = amount.toLongOrNull() ?: 0L,
                        type = BillType.EXPENSE,
                        category = category,
                    )
                )
            }
        ) {
            Text(text = "添加")
        }
    }
}

package qzwx.app.module_data.dao

import androidx.room.Dao

@Dao
interface QBillDao {

}

package qzwx.app.module_data.dao

import androidx.room.Dao
import androidx.room.Delete
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import kotlinx.coroutines.flow.Flow

// 根据您的实际包名可能需要手动导入 QBillEntity
// import qzwx.app.module_data.entity.QBillEntity

@Dao
interface QBillDao {
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertBill(bill: QBillEntity): Long

    @Delete
    suspend fun deleteBill(bill: QBillEntity)

    @Update
    suspend fun updateBill(bill: QBillEntity)

    @Query("SELECT * FROM QBillEntity ORDER BY `创建时间` DESC")
    fun getAllBills(): Flow<List<QBillEntity>>

    @Query("SELECT * FROM QBillEntity WHERE id = :id")
    suspend fun getBillById(id: Long): QBillEntity?
}
